import math
from typing import List, Tuple

def rotate_point(x: float, y: float, angle: float) -> Tuple[float, float]:
    rad = math.radians(angle)
    cos_a = math.cos(rad)
    sin_a = math.sin(rad)
    return x * cos_a - y * sin_a, x * sin_a + y * cos_a

def get_vertices(w: int, h: int, angle: int) -> List[Tuple[float, float]]:
    half_w = w / 2
    half_h = h / 2
    vertices = [
        (-half_w, -half_h),
        (half_w, -half_h),
        (half_w, half_h),
        (-half_w, half_h)
    ]
    return [rotate_point(x, y, angle) for x, y in vertices]

def intersection_area(rect1: List[Tuple[float, float]], rect2: List[Tuple[float, float]]) -> float:
    def orientation(p: Tuple[float, float], q: Tuple[float, float], r: Tuple[float, float]) -> int:
        val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
        if val == 0:
            return 0
        return 1 if val > 0 else 2

    def do_intersect(p1: Tuple[float, float], q1: Tuple[float, float], p2: Tuple[float, float], q2: Tuple[float, float]) -> bool:
        o1 = orientation(p1, q1, p2)
        o2 = orientation(p1, q1, q2)
        o3 = orientation(p2, q2, p1)
        o4 = orientation(p2, q2, q1)

        if o1 != o2 and o3 != o4:
            return True
        if o1 == 0 and is_on_segment(p1, p2, q1):
            return True
        if o2 == 0 and is_on_segment(p1, q2, q1):
            return True
        if o3 == 0 and is_on_segment(p2, p1, q2):
            return True
        if o4 == 0 and is_on_segment(p2, q1, q2):
            return True
        return False

    def is_on_segment(p: Tuple[float, float], q: Tuple[float, float], r: Tuple[float, float]) -> bool:
        return (q[0] <= max(p[0], r[0]) and q[0] >= min(p[0], r[0]) and
                q[1] <= max(p[1], r[1]) and q[1] >= min(p[1], r[1]))

    def polygon_area(points: List[Tuple[float, float]]) -> float:
        n = len(points)
        area = 0.0
        for i in range(n):
            j = (i + 1) % n
            area += points[i][0] * points[j][1]
            area -= points[j][0] * points[i][1]
        area = abs(area) / 2.0
        return area

    def compute_intersection(rect1: List[Tuple[float, float]], rect2: List[Tuple[float, float]]) -> List[Tuple[float, float]]:
        intersection_points = []
        for i in range(4):
            for j in range(4):
                if do_intersect(rect1[i], rect1[(i + 1) % 4], rect2[j], rect2[(j + 1) % 4]):
                    intersection_points.append((rect1[i][0], rect1[i][1]))
                    break
        return intersection_points

    intersection_points = compute_intersection(rect1, rect2)
    if len(intersection_points) < 3:
        return 0.0
    return polygon_area(intersection_points)

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    w = int(data[0])
    h = int(data[1])
    alpha = int(data[2])

    rect1 = get_vertices(w, h, 0)
    rect2 = get_vertices(w, h, alpha)

    area = intersection_area(rect1, rect2)
    print(f"{area:.9f}")

if __name__ == "__main__":
    main()
